<template><article class="product-card"><RouterLink :to="'/products/'+product.slug" class="product-image"><img :src="product.image" :alt="product.name" loading="lazy"><span v-if="product.tag" class="tag">{{product.tag}}</span><span class="quick-view">View details ↗</span></RouterLink><div class="product-info"><div class="product-meta">{{product.category}} <span>{{product.size}}</span></div><RouterLink :to="'/products/'+product.slug" class="product-name">{{product.name}}</RouterLink><p>{{product.short}}</p><div class="price-line"><strong>{{money(product.price)}}</strong><del>{{money(product.compareAt)}}</del></div><RouterLink :to="'/products/'+product.slug" class="text-link">Choose options <span>→</span></RouterLink></div></article></template>
